// Member D starts here: dashboard prediction uses these generated model coefficients.
// Generated by ml/train_and_evaluate.py. Do not edit coefficients by hand.
// Source: Kaggle pythonafroz/pv-plant-in-normal-and-shading-faults-conditions; power is normalized to a 150 W demo module.
export const ML_MODEL_METRICS = {
  "r2": 0.8727907981200032,
  "mae_w": 12.637935793639196,
  "rmse_w": 16.42620051349428,
  "test_rows": 8016
};
export const FAULT_CLASSES = [0.0, 1.0, 2.1, 2.2, 2.3, 3.1, 3.2, 4.0];
export const PANEL_RATING_W = 150.0;
const INTERCEPT = -0.023824512979017498;
const COEFFICIENTS = [0.5849041246571351, 0.05004964212125769, 0.14192285617374553, -0.3216860946224573, 0.08623906430922808, -0.04882345634319285, -0.0958295732268722, 0.07684126855906534, 0.13474267942713414, 0.026593253781367517];

export function faultClassForSoiling(percent) {
  if (percent < 12) return 0.0;
  if (percent < 35) return 2.1;
  if (percent < 55) return 2.2;
  return 2.3;
}

export function predictPowerML(irradiance, temperature, faultClass = 0) {
  const x = [irradiance / 1000, (temperature - 25) / 25,
    ...FAULT_CLASSES.map((fault) => fault === faultClass ? 1 : 0)];
  let normalized = INTERCEPT;
  for (let i = 0; i < x.length; i++) normalized += COEFFICIENTS[i] * x[i];
  return Number((Math.max(0, Math.min(1.15, normalized)) * PANEL_RATING_W).toFixed(1));
}

export function predictOperatingPower(irradiance, temperature, faultClass = 0, angle = 20, optimalAngle = 20) {
  const thermalFactor = Math.max(0.7, 1 - 0.004 * Math.max(0, temperature - 25));
  const angleFactor = Math.max(0, Math.cos(Math.abs(angle - optimalAngle) * Math.PI / 180));
  return Number((predictPowerML(irradiance, 25, faultClass) * thermalFactor * angleFactor).toFixed(1));
}
